/**
 * The client's key list mirrors the server catalogue. shared/permission-keys.json
 * is regenerated by a backend test from app/services/permissions.py, so a key
 * added, renamed or removed on either side fails here.
 */
import { describe, it, expect } from 'vitest';
import catalogue from '../../../../shared/permission-keys.json';
import { APPROVABLE_KEYS, PERMISSION_KEYS, PM_BUNDLE } from '@/types/permissions';

const sorted = (keys: Iterable<string>) => [...keys].sort();

describe('permission catalogue mirror', () => {
  it('names exactly the server keys', () => {
    expect(sorted(PERMISSION_KEYS)).toEqual(sorted(catalogue.keys));
    expect(new Set(PERMISSION_KEYS).size).toBe(PERMISSION_KEYS.length);
  });

  it('marks the same keys approvable', () => {
    expect(sorted(APPROVABLE_KEYS)).toEqual(sorted(catalogue.approvable));
  });

  it('uses the same project-manager bundle', () => {
    expect(sorted(PM_BUNDLE)).toEqual(sorted(catalogue.pm_bundle));
  });
});
